import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Crimson Project Update - Samuel Just, IBM","description":"","frontmatter":{"title":"Crimson Project Update - Samuel Just, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","Crimson项目","分布式存储","OSD","物理存储","虚拟化","云计算"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Crimson_Project_Update_-_Samuel_Just_IBM.md","filePath":"posts/2023/Crimson_Project_Update_-_Samuel_Just_IBM.md","lastUpdated":1780459816000}'),r={name:"posts/2023/Crimson_Project_Update_-_Samuel_Just_IBM.md"};function o(s,l,n,u,m,_){return i(),a("div",null,[...l[0]||(l[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-crimson项目介绍及reef更新" tabindex="-1">会议主题：Crimson项目介绍及Reef更新 <a class="header-anchor" href="#会议主题-crimson项目介绍及reef更新" aria-label="Permalink to &quot;会议主题：Crimson项目介绍及Reef更新&quot;">​</a></h4><h4 id="主讲人-samuel-just-ibm" tabindex="-1">主讲人：Samuel Just, IBM <a class="header-anchor" href="#主讲人-samuel-just-ibm" aria-label="Permalink to &quot;主讲人：Samuel Just, IBM&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Crimson项目概述</strong>：</p><ul><li>Crimson项目旨在优化Ceph OSD（Object Storage Daemon）的性能，特别是在高IOPS环境下。</li><li>通过减少跨核心通信、拷贝和上下文切换，以及利用NVMe、ZNS和SMR等新兴存储技术来减少CPU开销。</li></ul></li><li><p><strong>技术背景</strong>：</p><ul><li>存储技术进步导致IOPS大幅提升，但CPU性能未能同步提升，造成单个IO的CPU开销增加。</li><li>多核心架构虽然提高了整体性能，但增加了延迟和核心间通信开销。</li></ul></li><li><p><strong>现有架构问题</strong>：</p><ul><li>传统OSD架构涉及多个线程池和队列，导致锁竞争和非确定性延迟。</li><li>在处理请求提交回调和PG状态时，存在性能瓶颈。</li></ul></li><li><p><strong>Crimson架构设计</strong>：</p><ul><li>采用C-star库，支持在单个线程上多路复用异步操作。</li><li>通过future和callback机制，优化请求处理的同步和异步操作。</li></ul></li><li><p><strong>C-store介绍</strong>：</p><ul><li>C-store是专为Crimson设计的对象存储实现，利用ZNS等新兴存储技术。</li><li>避免使用CPU密集型的元数据设计，支持高效的垃圾回收和数据迁移。</li></ul></li><li><p><strong>当前进展和未来计划</strong>：</p><ul><li>已支持RBD工作负载和复制池，Blue Store和C-store后端均已实现。</li><li>正在进行多核心支持的开发，以及增强稳定性和性能测试。</li><li>未来计划包括完善测试套件，实现数据校验（scrub），以及进一步优化多核心架构下的消息路由。</li></ul></li><li><p><strong>用户参与和反馈</strong>：</p><ul><li>鼓励用户通过设置实验性功能标志来测试Crimson，但目前不建议用于生产环境。</li><li>用户反馈和性能测试数据对项目发展至关重要。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>完善测试套件，特别是数据校验（scrub）功能的实现。</li><li>继续优化多核心支持，改进消息路由和调度机制。</li><li>增强C-store的稳定性和性能，特别是针对ZNS和NVMe的优化。</li><li>收集用户反馈，持续迭代和优化Crimson项目。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>主讲人感谢大家的参与，并邀请提问和讨论。</li></ul>',9)])])}const p=e(r,[["render",o]]);export{c as __pageData,p as default};
